function inactive(){const ps=S.p.filter(p=>p.activo===false);return '<div class="card"><h2>📁 Inactivos</h2>'+(!ps.length?'<div class="empty">No hay productos inactivos.</div>':ps.map(p=>`<div class="inactive row"><div><b>${esc(p.nombre)}</b><div class="sub">${esc(tn(p))}</div></div><button class="btn alt" onclick="activate('${p.id}')">Reactivar</button></div>`).join(''))+'</div>'}
function sources(){return '<div class="card"><h2>Fuentes de valoración</h2>'+(!S.sources.length?'<div class="empty">No hay fuentes configuradas.</div>':S.sources.map(s=>`<div class="row"><span><b>${esc(s.nombre)}</b><div class="sub">${esc(s.tipo_fuente||'')} · ${s.gratuita?'Gratuita':'De pago'}</div></span><span class="pill ${s.activa?'ok':'warn'}">${s.activa?'Activa':'Inactiva'}</span></div>`).join(''))+'</div>'}
function historyImporter(){return '<div class="card"><h2>📥 Importar histórico CSV</h2><div class="notice">Importa cierres históricos de un producto. Se conservan los datos existentes y se ignoran automáticamente las fechas duplicadas.</div><div class="form"><label>Producto<select id="impP">'+active().filter(p=>!account(p)).map(p=>'<option value="'+p.id+'" '+(p.id===S.context?'selected':'')+'>'+esc(p.nombre)+'</option>').join('')+'</select></label><label>Archivo CSV<input id="impFile" type="file" accept=".csv,text/csv"></label><label class="full">Formato de columnas<textarea id="impInfo" rows="3" placeholder="Ejemplo: Date,Close\\n21/08/2026,18.250"></textarea></label></div><div style="margin-top:12px"><button class="btn" onclick="importHistoryCsv()">Importar histórico</button></div><div id="impResult" class="sub" style="margin-top:12px"></div></div>'}
function parseCsvText(txt){const lines=txt.replace(/^\uFEFF/,'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return[];const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const rows=lines.map(line=>{const a=[];let cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){q=!q;continue}if(c===sep&&!q){a.push(cur.trim());cur=''}else cur+=c}a.push(cur.trim());return a});const head=rows.shift().map(x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''));const di=head.findIndex(x=>x==='date'||x==='fecha'||x.includes('date')||x.includes('fecha'));const ci=head.findIndex(x=>x==='close'||x==='cierre'||x.includes('close')||x.includes('cierre'));return rows.map(r=>{let ds=r[di],cs=r[ci];if(!ds||!cs)return null;let d;if(/^\d{2}[\/-]\d{2}[\/-]\d{4}$/.test(ds)){const [dd,mm,yy]=ds.split(/[\/-]/);d=yy+'-'+mm+'-'+dd}else if(/^\d{4}[\/-]\d{2}[\/-]\d{2}/.test(ds))d=ds.slice(0,10);else{const z=new Date(ds);if(isNaN(z))return null;d=z.toISOString().slice(0,10)}let n=String(cs).replace(/\s/g,'').replace(/€/g,'');if(n.includes(',')&&n.includes('.')){if(n.lastIndexOf(',')>n.lastIndexOf('.'))n=n.replace(/\./g,'').replace(',','.');else n=n.replace(/,/g,'')}else n=n.replace(',','.');const c=Number(n);return d&&Number.isFinite(c)?{fecha:d,cierre:c}:null}).filter(Boolean)}
async function importHistoryCsv(){const pid=$('impP').value,file=$('impFile').files[0],out=$('impResult');if(!file)return out.textContent='Selecciona un CSV.';out.textContent='Procesando…';try{const txt=await file.text(),rows=parseCsvText(txt);if(!rows.length)throw new Error('No se han encontrado filas con Fecha y Cierre.');const existing=await db.from('cotizaciones_historicas').select('fecha').eq('producto_id',pid);if(existing.error)throw existing.error;const seen=new Set((existing.data||[]).map(x=>String(x.fecha).slice(0,10)));const unique=[...new Map(rows.filter(x=>!seen.has(x.fecha)).map(x=>[x.fecha,x])).values()];if(!unique.length){out.textContent='No hay fechas nuevas que importar.';return}const payload=unique.map(x=>({user_id:S.user.id,producto_id:pid,fecha:x.fecha,cierre:x.cierre,moneda:'EUR',tipo_precio:'Cierre',origen:'Importación CSV',fuente:file.name,es_valida:true,prioridad_origen:50}));for(let i=0;i<payload.length;i+=500){const r=await db.from('cotizaciones_historicas').insert(payload.slice(i,i+500));if(r.error)throw r.error}S.qLoaded[pid]=false;out.textContent='Hecho: '+unique.length+' registros nuevos importados.';await load()}catch(e){out.textContent='Error: '+(e.message||e)}}
function library(){return '<div class="card"><h2>📚 Biblioteca</h2><div class="section"><div class="section-title">Fuentes</div>'+(!S.sources.length?'<div class="empty">No hay fuentes.</div>':S.sources.map(s=>`<div class="library-item"><b>${esc(s.nombre)}</b><div class="sub">${esc(s.tipo_fuente||'')} · ${s.ofrece_historico?'Histórico disponible':'Sin histórico declarado'} · ${s.tiempo_real?'Tiempo real':'Fin de día / diferido'}</div></div>`).join(''))+'</div><div class="section"><div class="section-title">Documentos de productos</div>'+(!S.docs.length?'<div class="empty">Todavía no hay documentos.</div>':S.docs.map(d=>`<div class="library-item"><b>📎 ${esc(d.archivo_nombre)}</b><div class="sub">${esc(S.p.find(p=>p.id===d.producto_id)?.nombre||'Producto')} · ${date(d.fecha_documento)} · ${esc(d.estado||'')}</div></div>`).join(''))+'</div></div>'}
function editInterest(id){const x=S.i.find(v=>v.id===id);if(!x)return alert('No se encontró el interés.');modalBox.innerHTML=`<h2>Editar interés</h2><div class="form"><label>Cuenta<select id="eiProduct">${S.p.filter(account).map(p=>'<option value="'+p.id+'" '+(p.id===x.producto_id?'selected':'')+'>'+esc(p.nombre)+'</option>').join('')}</select></label><label>Fecha<input id="eiDate" type="date" value="${String(x.fecha).slice(0,10)}"></label><label>Bruto<input id="eiGross" type="number" step="0.01" value="${Number(x.importe_bruto)||0}"></label><label>Retención<input id="eiTax" type="number" step="0.01" value="${Number(x.retencion)||0}"></label><label>Neto<input id="eiNet" type="number" step="0.01" value="${Number(x.importe_neto)||0}"></label><label class="full">Observaciones<textarea id="eiObs">${esc(x.observaciones||'')}</textarea></label></div><br><button class="btn" onclick="saveInterestEdit('${id}')">Guardar cambios</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveInterestEdit(id){const r=await db.from('intereses_cuentas').update({producto_id:$('eiProduct').value,fecha:$('eiDate').value,importe_bruto:Number($('eiGross').value)||0,retencion:Number($('eiTax').value)||0,importe_neto:Number($('eiNet').value)||0,observaciones:$('eiObs').value}).eq('id',id).eq('user_id',S.user.id);if(r.error)return alert('No se pudo actualizar: '+r.error.message);closeM();await load()}
async function deleteInterest(id){if(!confirm('¿Eliminar este registro de intereses? Esta acción no se puede deshacer.'))return;const r=await db.from('intereses_cuentas').delete().eq('id',id).eq('user_id',S.user.id);if(r.error)return alert('No se pudo eliminar: '+r.error.message);await load()}
function interests(){const rows=S.i.slice().sort((a,b)=>String(b.fecha||'').localeCompare(String(a.fecha||'')));const sum=(arr,k)=>arr.reduce((t,x)=>t+(Number(x[k])||0),0);const entities=[...new Set(rows.map(x=>{const p=S.p.find(p=>p.id===x.producto_id);return p?en(p):'Sin entidad'}))].sort((a,b)=>a.localeCompare(b,'es'));return '<div class="card"><div class="toolbar" style="gap:8px;margin-bottom:12px;align-items:center"><h2 style="font-size:22px;margin:0">Intereses</h2><button class="btn" style="padding:7px 12px;font-size:14px;min-height:34px" onclick="interestForm()">＋ Añadir interés</button><button class="btn secondary" style="padding:7px 12px;font-size:14px;min-height:34px" onclick="captureInterest()">📷 Importar captura / documento</button></div>'+(!rows.length?'<div class="empty">No hay intereses registrados.</div>':'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0 10px"><label for="interestEntityFilter" style="font-weight:800;font-size:14px">Filtrar por entidad:</label><select id="interestEntityFilter" onchange="filterInterestRows()" style="padding:6px 10px;border:1px solid #b8c8dc;border-radius:6px;background:#fff;min-width:200px;font-size:14px"><option value="">Todas las entidades</option>'+entities.map(e=>'<option value="'+esc(e)+'">'+esc(e)+'</option>').join('')+'</select><button class="btn secondary" onclick="document.getElementById(\'interestEntityFilter\').value=\'\';filterInterestRows()">Limpiar filtro</button></div><div style="overflow-x:auto"><table id="interestGrid" class="data-table" style="width:100%;border-collapse:collapse;min-width:760px;border:1px solid #aebed1;font-size:14px;line-height:1.05"><thead><tr style="background:#eaf0f7"><th style="text-align:left;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Fecha</th><th style="text-align:left;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Entidad / cuenta</th><th style="text-align:right;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Intereses brutos</th><th style="text-align:right;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Retención</th><th style="text-align:right;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Intereses netos</th><th style="text-align:left;padding:4px 6px;line-height:1.1;border:1px solid #aebed1">Acciones</th></tr></thead><tbody>'+rows.map(x=>{const p=S.p.find(p=>p.id===x.producto_id),entity=p?en(p):'Sin entidad';return '<tr data-entity="'+esc(entity)+'"><td style="padding:1px 5px;line-height:1.05;border:1px solid #c6d0dc;white-space:nowrap">'+date(x.fecha)+'</td><td style="padding:1px 5px;line-height:1.05;border:1px solid #c6d0dc">'+esc(p?.nombre||'Producto no identificado')+' <span class="sub" style="display:inline;margin-left:5px;font-size:12px;white-space:nowrap">· '+esc(entity)+'</span></td><td style="padding:1px 5px;line-height:1.05;border:1px solid #c6d0dc;text-align:right;white-space:nowrap">'+money(x.importe_bruto)+'</td><td style="padding:1px 5px;line-height:1.05;border:1px solid #c6d0dc;text-align:right;white-space:nowrap">'+money(x.retencion)+'</td><td style="padding:1px 5px;line-height:1.05;border:1px solid #c6d0dc;text-align:right;white-space:nowrap;font-weight:800">'+money(x.importe_neto)+'</td><td style="padding:1px 5px;border:1px solid #c6d0dc;white-space:nowrap"><button class="btn alt" onclick="editInterest(\''+x.id+'\')">Editar</button> <button class="btn red" onclick="deleteInterest(\''+x.id+'\')">Eliminar</button></td></tr>'}).join('')+'</tbody><tfoot><tr style="background:#f1f5f9;font-weight:800"><td colspan="2" style="padding:4px 6px;line-height:1.1;border:1px solid #aebed1">TOTAL VISIBLE</td><td id="interestTotalGross" style="padding:4px 6px;text-align:right;line-height:1.1;border:1px solid #aebed1">'+money(sum(rows,'importe_bruto'))+'</td><td id="interestTotalTax" style="padding:4px 6px;text-align:right;line-height:1.1;border:1px solid #aebed1">'+money(sum(rows,'retencion'))+'</td><td id="interestTotalNet" style="padding:4px 6px;text-align:right;line-height:1.1;border:1px solid #aebed1">'+money(sum(rows,'importe_neto'))+'</td></tr></tfoot></table></div>')+'</div>'}
function filterInterestRows(){const table=document.getElementById('interestGrid');if(!table)return;const selected=document.getElementById('interestEntityFilter').value;const visible=[];table.querySelectorAll('tbody tr').forEach(row=>{const show=!selected||row.dataset.entity===selected;row.style.display=show?'':'none';if(show){const cells=row.cells;visible.push({gross:parseInterestMoney(cells[2].textContent),tax:parseInterestMoney(cells[3].textContent),net:parseInterestMoney(cells[4].textContent)})}});const totals=[['interestTotalGross','gross'],['interestTotalTax','tax'],['interestTotalNet','net']];totals.forEach(([id,key])=>{const el=document.getElementById(id);if(el)el.textContent=money(visible.reduce((s,x)=>s+x[key],0))})}
function parseInterestMoney(value){return Number(String(value).replace(/[^0-9,.-]/g,'').replace(/\./g,'').replace(',','.'))||0}

function quoteHistory(id){const qh=histQ(id),vh=histV(id),m=new Map();qh.forEach(q=>m.set(String(q.fecha).slice(0,10),{fecha:q.fecha,cot:q.cierre,total:Number(q.cierre||0)*qty(id),origen:'Cotización',qrow:q}));vh.forEach(v=>{const k=String(v.fecha).slice(0,10),r=m.get(k)||{fecha:v.fecha};r.total=v.valor_total;r.cot=r.cot??v.precio_unitario;r.origen=r.origen?r.origen+' + '+(v.origen||'Valoración'):(v.origen||'Valoración');r.vrow=v;m.set(k,r)});const rows=[...m.values()].sort((a,b)=>String(b.fecha).localeCompare(String(a.fecha)));const page=25,start=S.historyPage*page,part=rows.slice(start,start+page);if(!rows.length)return '<div class="empty">Sin histórico.</div>';const body=part.map(r=>{const vmanual=r.vrow&&String(r.vrow.origen||'').toLowerCase()==='manual',qmanual=r.qrow&&String(r.qrow.origen||'').toLowerCase()==='manual';const actions=vmanual?`<button class="btn alt" onclick="editManualValuation('${r.vrow.id}')">Editar valoración</button> <button class="btn red" onclick="deleteManualValuation('${r.vrow.id}')">Eliminar valoración</button>`:''+(qmanual?`<button class="btn alt" onclick="editManualQuote('${r.qrow.id}')">Editar cotización</button> <button class="btn red" onclick="deleteManualQuote('${r.qrow.id}')">Eliminar cotización</button>`:'');return `<tr><td>${date(r.fecha)}</td><td>${r.cot==null?'—':num(r.cot)+' €'}</td><td>${r.total==null?'—':money(r.total)}</td><td>${esc(r.origen||'')}</td><td>${actions||'—'}</td></tr>`}).join('');const prevDisabled=start===0?'disabled':'';const nextDisabled=start+page>=rows.length?'disabled':'';return `<table class="history"><thead><tr><th>Fecha</th><th>Cotización/valor</th><th>Total</th><th>Origen</th><th>Acciones</th></tr></thead><tbody>${body}</tbody></table><div class="toolbar" style="margin-top:12px"><span class="sub">${start+1}-${Math.min(start+page,rows.length)} de ${rows.length}</span><span><button class="btn alt" ${prevDisabled} onclick="S.historyPage--;product('${id}')">Anterior</button> <button class="btn alt" ${nextDisabled} onclick="S.historyPage++;product('${id}')">Siguiente</button></span></div>`}
async function product(id){const p=S.p.find(x=>x.id===id);if(!p)return;if(S.context!==id)S.historyPage=0;S.context=id;try{if(!account(p)&&!S.qLoaded[id])await ensureQuotes(id);const unit=currentUnit(p),c=cost(p),d=diff(p),pc=pct(p);modalBox.innerHTML=`<div class="toolbar"><h2>${esc(p.nombre)}</h2><button class="btn alt" onclick="closeM()">Cerrar</button></div><div class="sub">${esc(en(p))} · ${esc(tn(p))}</div><div class="toolbar" style="margin:15px 0"><button class="btn" onclick="manualData('${id}')">＋ Introducir datos</button><button class="btn alt" onclick="capture('${id}')">📎 Captura / PDF / Word / Excel</button>${account(p)?'':'<button class="btn alt" onclick="operationForm(\''+id+'\')">＋ Operación</button>'}${p.activo!==false?'<button class="btn red" onclick="deactivate(\''+id+'\')">Pasar a inactivos</button>':''}</div>${account(p)?((window.PatrimonioDashboard&&typeof window.PatrimonioDashboard.accountChart==='function'?window.PatrimonioDashboard.accountChart(id):'')+accountHistory(p)):`<div class="card"><table class="history"><thead><tr><th>Posición</th><th>Coste</th><th>Coste medio</th><th>Última cotización/valor liquidativo</th><th>Fecha</th><th>Valor actual</th><th>Diferencia</th><th>%</th></tr></thead><tbody><tr><td>${num(qty(id))}</td><td>${c==null?'—':money(c)}</td><td>${c==null||!qty(id)?'—':num(c/qty(id))+' €'}</td><td>${unit==null?'—':num(unit)+' €'}</td><td>${date(currentDate(p))}</td><td>${money(val(p))}</td><td class="${d>0?'gain':d<0?'loss':''}">${d?(d>0?'+':'')+money(d):'—'}</td><td class="${pc>0?'gain':pc<0?'loss':''}">${pc?(pc>0?'+':'')+pc.toFixed(2)+' %':'—'}</td></tr></tbody></table></div>`}<div class="card"><h3>Histórico completo de cotizaciones / valoraciones</h3>${quoteHistory(id)}</div><div class="card"><h3>Operaciones</h3>${opsHistory(id)}</div><div class="card"><h3>Documentos asociados</h3>${docsHistory(id)}</div>`;if(account(p)){let keptChart=false;modalBox.querySelectorAll('.card').forEach(card=>{const h=card.querySelector('h3');if(h&&/^Evolución(?: del saldo)?$/.test(h.textContent.trim())){if(!keptChart){keptChart=true;h.textContent='Evolución';}else card.remove();}})};modal.classList.add('open')}catch(e){alert('No se pudo cargar el histórico: '+(e.message||e))}}
function editManualQuote(id){const x=S.q.find(v=>v.id===id);if(!x)return alert('No se encontró la cotización manual.');modalBox.innerHTML=`<h2>Editar cotización manual</h2><div class="form"><label>Fecha<input id="eqDate" type="date" value="${String(x.fecha).slice(0,10)}"></label><label>Valor de cotización (€)<input id="eqValue" type="number" step="0.00000001" value="${Number(x.cierre)||0}"></label><label class="full">Observaciones<textarea id="eqObs">${esc(x.observaciones||'')}</textarea></label></div><br><button class="btn" onclick="saveManualQuote('${id}')">Guardar cambios</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveManualQuote(id){const r=await db.from('cotizaciones_historicas').update({fecha:$('eqDate').value,cierre:Number($('eqValue').value)||0,observaciones:$('eqObs').value}).eq('id',id).eq('user_id',S.user.id).eq('origen','manual');if(r.error)return alert('No se pudo actualizar: '+r.error.message);closeM();await load();if(S.context)product(S.context)}
async function deleteManualQuote(id){if(!confirm('¿Eliminar esta cotización manual? Esta acción no se puede deshacer.'))return;const r=await db.from('cotizaciones_historicas').delete().eq('id',id).eq('user_id',S.user.id).eq('origen','manual');if(r.error)return alert('No se pudo eliminar: '+r.error.message);closeM();await load()}
function editManualValuation(id){const x=S.v.find(v=>v.id===id);if(!x)return alert('No se encontró el dato.');modalBox.innerHTML=`<h2>Editar saldo / valoración</h2><div class="form"><label>Fecha<input id="evDate" type="date" value="${String(x.fecha).slice(0,10)}"></label><label>Saldo / valor total (€)<input id="evValue" type="number" step="0.00000001" value="${Number(x.valor_total)||0}"></label><label class="full">Observaciones<textarea id="evObs">${esc(x.observaciones||'')}</textarea></label></div><br><button class="btn" onclick="saveManualValuation('${id}')">Guardar cambios</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveManualValuation(id){const r=await db.from('valoraciones_historicas').update({fecha:$('evDate').value,valor_total:Number($('evValue').value)||0,observaciones:$('evObs').value}).eq('id',id).eq('user_id',S.user.id);if(r.error)return alert('No se pudo actualizar: '+r.error.message);closeM();await load();if(S.context)product(S.context)}
async function deleteManualValuation(id){if(!confirm('¿Eliminar este dato manual? Esta acción no se puede deshacer.'))return;const r=await db.from('valoraciones_historicas').delete().eq('id',id).eq('user_id',S.user.id).eq('origen','manual');if(r.error)return alert('No se pudo eliminar: '+r.error.message);await load();if(S.context)product(S.context)}
function editOperation(id){const x=S.o.find(v=>v.id===id);if(!x)return alert('No se encontró la operación.');modalBox.innerHTML=`<h2>Editar operación</h2><div class="form"><label>Fecha<input id="eoDate" type="date" value="${String(x.fecha).slice(0,10)}"></label><label>Tipo<select id="eoType">${['Compra','Venta','Aportación','Dividendo en acciones','Acciones liberadas','Split','Ajuste de posición','Traspaso'].map(t=>'<option '+(t===x.tipo_operacion?'selected':'')+'>'+t+'</option>').join('')}</select></label><label>Cantidad<input id="eoQty" type="number" step="0.00000001" value="${Number(x.cantidad)||0}"></label><label>Precio unitario (€)<input id="eoPrice" type="number" step="0.00000001" value="${Number(x.precio_unitario)||0}"></label><label>Importe neto (€)<input id="eoNet" type="number" step="0.01" value="${Number(x.importe_neto)||0}"></label><label class="full">Observaciones<textarea id="eoObs">${esc(x.observaciones||'')}</textarea></label></div><br><button class="btn" onclick="saveOperation('${id}')">Guardar cambios</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveOperation(id){const r=await db.from('operaciones').update({fecha:$('eoDate').value,tipo_operacion:$('eoType').value,cantidad:Number($('eoQty').value)||0,precio_unitario:Number($('eoPrice').value)||0,importe_neto:Number($('eoNet').value)||0,observaciones:$('eoObs').value}).eq('id',id).eq('user_id',S.user.id);if(r.error)return alert('No se pudo actualizar: '+r.error.message);closeM();await load();if(S.context)product(S.context)}
async function deleteOperation(id){if(!confirm('¿Eliminar esta operación? Se recalcularán la posición y el coste del producto.'))return;const r=await db.from('operaciones').delete().eq('id',id).eq('user_id',S.user.id);if(r.error)return alert('No se pudo eliminar: '+r.error.message);closeM();await load()}
function accountHistory(p){const h=histV(p.id),page=25,start=S.historyPage*page,part=h.slice(start,start+page);if(!h.length)return '<div class="card"><h3>Histórico de saldos</h3><div class="empty">Sin histórico.</div></div>';const body=part.map((x,i)=>{const idx=start+i,prev=h[idx+1],d=prev?Number(x.valor_total)-Number(prev.valor_total):null,manual=String(x.origen||'').toLowerCase()==='manual';return `<tr><td>${date(x.fecha)}</td><td>${money(x.valor_total)}</td><td class="${d>0?'gain':d<0?'loss':''}">${d==null?'—':(d>0?'+':'')+money(d)}</td><td>${manual?`<button class="btn alt" onclick="editManualValuation('${x.id}')">Editar</button> <button class="btn red" onclick="deleteManualValuation('${x.id}')">Eliminar</button>`:'—'}</td></tr>`}).join('');const prevDisabled=start===0?'disabled':'',nextDisabled=start+page>=h.length?'disabled':'';return '<div class="card"><h3>Histórico de saldos</h3><table class="history"><thead><tr><th>Fecha</th><th>Saldo</th><th>Diferencia</th><th>Acciones</th></tr></thead><tbody>'+body+'</tbody></table><div class="toolbar" style="margin-top:12px"><span class="sub">'+(start+1)+'-'+Math.min(start+page,h.length)+' de '+h.length+'</span><span><button class="btn alt" '+prevDisabled+' onclick="S.historyPage--;product(\''+p.id+'\')">Anterior</button> <button class="btn alt" '+nextDisabled+' onclick="S.historyPage++;product(\''+p.id+'\')">Siguiente</button></span></div></div>'}
function opsHistory(id){const a=S.o.filter(x=>x.producto_id===id).sort((a,b)=>String(b.fecha).localeCompare(String(a.fecha)));return a.length?'<table class="history"><thead><tr><th>Fecha</th><th>Tipo</th><th>Cantidad</th><th>Precio</th><th>Acciones</th></tr></thead><tbody>'+a.map(x=>`<tr><td>${date(x.fecha)}</td><td>${esc(x.tipo_operacion)}</td><td>${num(x.cantidad)}</td><td>${money(x.precio_unitario)}</td><td><button class="btn alt" onclick="editOperation('${x.id}')">Editar</button> <button class="btn red" onclick="deleteOperation('${x.id}')">Eliminar</button></td></tr>`).join('')+'</tbody></table>':'<div class="empty">Sin operaciones.</div>'}
function docsHistory(id){const a=S.docs.filter(x=>x.producto_id===id);return a.length?a.map(x=>`<div class="row"><span>📎 ${esc(x.archivo_nombre)}<br><small class="sub">${date(x.fecha_documento)} · ${esc(x.estado)}</small></span></div>`).join(''):'<div class="empty">No hay documentos asociados.</div>'}
function editProduct(id){const p=S.p.find(x=>x.id===id);if(!p)return;modalBox.innerHTML='<h2>Editar producto</h2><div class="form"><label>Entidad<select id="editEntity">'+S.e.filter(e=>e.activo!==false).map(e=>'<option value="'+e.id+'" '+(e.id===p.entidad_financiera_id?'selected':'')+'>'+esc(e.nombre)+'</option>').join('')+'</select></label><label>Tipo<select id="editType">'+S.t.filter(t=>t.activo!==false).map(t=>'<option value="'+t.id+'" '+(t.id===p.tipo_producto_id?'selected':'')+'>'+esc(t.nombre)+'</option>').join('')+'</select></label><label class="full">Nombre<input id="editName" value="'+esc(p.nombre)+'"></label><label>ISIN<input id="editIsin" value="'+esc(p.isin||'')+'"></label><label>Ticker<input id="editTicker" value="'+esc(p.ticker||'')+'"></label><label>Moneda<select id="editCurrency">'+['EUR','USD','GBP','CHF'].map(x=>'<option '+((p.moneda||'EUR')===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><p id="editStatus" class="sub full"></p></div><br><button class="btn" onclick="saveEditedProduct(\''+id+'\')">Guardar cambios</button> <button class="btn alt" onclick="closeM()">Cancelar</button>';modal.classList.add('open')}
async function saveEditedProduct(id){const p=S.p.find(x=>x.id===id),status=$('editStatus');if(!p)return;const nombre=$('editName').value.trim(),isin=$('editIsin').value.trim().toUpperCase();if(!nombre){status.textContent='El nombre es obligatorio.';return}if(isin&&!/^[A-Z0-9]{12}$/.test(isin)){status.textContent='El ISIN debe tener 12 caracteres o quedar vacío.';return}try{const changes={entidad_financiera_id:$('editEntity').value,tipo_producto_id:$('editType').value,nombre,isin:isin||null,ticker:$('editTicker').value.trim().toUpperCase()||null,moneda:$('editCurrency').value};const r=await db.from('productos').update(changes).eq('id',id).select('*').single();if(r.error)throw r.error;Object.assign(p,r.data);closeM();S.tab='entidades';S.open[p.entidad_financiera_id]=true;render()}catch(e){status.textContent='Error al guardar: '+e.message}}
async function deleteProduct(id) {
  const p = S.p.find(x => x.id === id);
  if (!p) return;
  try {
    if (!confirm('¿Comprobar si el producto ' + p.nombre + ' tiene datos asociados antes de eliminarlo?')) return;
    const refs = [['operaciones','producto_id'],['operaciones','producto_usuario_id'],['intereses_cuentas','producto_id'],['dividendos','producto_id'],['dividendos','producto_usuario_id'],['valoraciones_historicas','producto_id'],['valoraciones_historicas','producto_usuario_id'],['cotizaciones_historicas','producto_id'],['documentos_capturas','producto_id'],['cartera_componentes','producto_id'],['cartera_componentes','producto_usuario_id'],['historicos_cargas','producto_id'],['importaciones_posicion_detalle','producto_id'],['productos_fuentes','producto_id'],['productos_identificadores','producto_id'],['rendimientos_financieros','producto_id']];
    const found = [];
    for (const [table, col] of refs) {
      const q = await db.from(table).select('id', { count: 'exact', head: true }).eq(col, id);
      if (q.error) throw new Error('No se pudo comprobar ' + table + ': ' + q.error.message);
      if ((q.count || 0) > 0 && !found.includes(table)) found.push(table);
    }
    if (found.length) {
      if (!confirm('Este producto tiene datos asociados (' + found.join(', ') + '). No se borrará. ¿Quieres marcarlo como INACTIVO y conservar los datos?')) return;
      const r = await db.from('productos').update({ activo: false }).eq('id', id);
      if (r.error) throw r.error;
      p.activo = false; S.tab = 'entidades'; render();
      alert('Producto marcado como inactivo. Sus operaciones e históricos se conservan.');
      return;
    }
    if (!confirm('No se encontraron datos asociados. ¿Borrar definitivamente ' + p.nombre + '? Esta acción no se puede deshacer.')) return;
    const r = await db.from('productos').delete().eq('id', id);
    if (r.error) throw r.error;
    S.p = S.p.filter(x => x.id !== id); S.tab = 'entidades'; render();
    alert('Producto eliminado definitivamente.');
  } catch (e) {
    alert('No se pudo completar la operación con seguridad: ' + (e.message || e) + '. No se ha borrado el producto.');
  }
}
function newProduct(entityId){const entities=S.e.filter(e=>e.activo!==false);if(!entities.length){alert('Primero debes crear una entidad financiera.');return}modalBox.innerHTML='<h2>＋ Añadir a la entidad</h2><p class="sub">Primero puedes registrar la cuenta. Los productos de inversión se añaden después, cuando los necesites.</p><div class="form"><label class="full">¿Qué quieres añadir?<select id="npMode" onchange="refreshNewProductMode()"><option value="account">Crear una cuenta</option><option value="product">Añadir un producto de inversión</option></select></label><label class="full">Entidad financiera<select id="npEntity">'+entities.map(e=>'<option value="'+e.id+'" '+(e.id===entityId?'selected':'')+'>'+esc(e.nombre)+'</option>').join('')+'</select></label><div id="npDetails" class="full"></div><p id="npStatus" class="sub full"></p></div><br><button class="btn" id="npSave" onclick="saveNewProduct()">Crear cuenta</button> <button class="btn alt" onclick="closeM()">Cancelar</button>';refreshNewProductMode();modal.classList.add('open')}
function refreshNewProductMode(){const mode=$('npMode').value,types=S.t.filter(t=>t.activo!==false);$('npDetails').innerHTML=mode==='account'?'<label class="full">Tipo de cuenta<select id="npType">'+types.filter(t=>['Cuenta corriente','Cuenta de ahorro','Cuenta de inversión'].includes(t.nombre)).map(t=>'<option value="'+t.id+'">'+esc(t.nombre)+'</option>').join('')+'</select></label><label class="full">Nombre de la cuenta<input id="npName" type="text" maxlength="180" placeholder="Ej. Cuenta de inversión"></label><label>Moneda<select id="npCurrency"><option value="EUR">EUR (€)</option><option value="USD">USD ($)</option><option value="GBP">GBP (£)</option><option value="CHF">CHF</option></select></label>':'<label class="full">Tipo de producto<select id="npType">'+types.filter(t=>!['Cuenta corriente','Cuenta de ahorro','Cuenta de inversión'].includes(t.nombre)).map(t=>'<option value="'+t.id+'">'+esc(t.nombre)+'</option>').join('')+'</select></label><label class="full">Nombre del producto<input id="npName" type="text" maxlength="180" placeholder="Nombre del fondo, ETF, acciones…"></label><label>ISIN (opcional)<input id="npIsin" type="text" maxlength="12" placeholder="Ej. IE00BYX5MD61"></label><label>Ticker (opcional)<input id="npTicker" type="text" maxlength="30"></label><label>Moneda<select id="npCurrency"><option value="EUR">EUR (€)</option><option value="USD">USD ($)</option><option value="GBP">GBP (£)</option><option value="CHF">CHF</option></select></label>';$('npSave').textContent=mode==='account'?'Crear cuenta':'Crear producto'}
async function saveNewProduct(){const entityId=$('npEntity').value,typeId=$('npType').value,name=$('npName').value.trim(),mode=$('npMode').value,isin=mode==='product'?($('npIsin').value.trim().toUpperCase()):'',ticker=mode==='product'?($('npTicker').value.trim().toUpperCase()):'',currency=$('npCurrency').value,status=$('npStatus'),btn=$('npSave');if(!entityId||!typeId||!name){status.textContent='Selecciona la entidad, el tipo y escribe el nombre de la cuenta o producto.';return}if(isin&&!/^[A-Z0-9]{12}$/.test(isin)){status.textContent='El ISIN debe tener 12 caracteres alfanuméricos. Compruébalo o déjalo vacío.';return}const duplicate=S.p.find(p=>p.activo!==false&&p.entidad_financiera_id===entityId&&((isin&&String(p.isin||'').toUpperCase()===isin)||(!isin&&p.nombre.trim().toLowerCase()===name.toLowerCase()&&p.tipo_producto_id===typeId)));if(duplicate){status.textContent='Ya existe un producto con ese nombre o ISIN en esta entidad: '+duplicate.nombre;return}btn.disabled=true;status.textContent='Guardando…';try{const r=await db.from('productos').insert({user_id:S.user.id,entidad_financiera_id:entityId,tipo_producto_id:typeId,nombre:name,isin:isin||null,ticker:ticker||null,moneda:currency,activo:true}).select('*').single();if(r.error)throw r.error;S.p.push(r.data);S.tab='entidades';closeM();S.open[entityId]=true;render()}catch(e){status.textContent='No se pudo guardar: '+(e.message||e);btn.disabled=false}}
function manualData(id){id=id||S.context||'';modalBox.innerHTML=`<h2>Introducir datos manualmente</h2><div class="sub">${id?'Producto seleccionado: '+esc(S.p.find(x=>x.id===id)?.nombre||''):'Selecciona el producto.'}</div><div class="form"><label>Producto<select id="mdp" onchange="manualRefresh()">${active().map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.nombre)}</option>`).join('')}</select></label><label>Fecha<input id="mdf" type="date" value="${today()}"></label><div id="manualFields" class="full"></div></div><br><button class="btn" onclick="saveManual()">Guardar</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;manualRefresh();if(account(S.p.find(x=>x.id===id)))modalBox.querySelector('button.btn.alt').insertAdjacentHTML('beforebegin',' <button class="btn alt" onclick="multiAccountData()">Introducción múltiple</button>');modal.classList.add('open')}
function manualRefresh(){const p=S.p.find(x=>x.id===$('mdp').value);$('manualFields').innerHTML=account(p)?'<div class="form"><label class="full">Saldo<input id="mdv" type="number" step="0.00000001"></label><label class="full">Observaciones<textarea id="mdo"></textarea></label></div>':'<div class="form"><label>Tipo<select id="mdt"><option value="valoracion">Valoración / valor liquidativo</option><option value="operacion">Operación / aportación</option></select></label><label>Cantidad / participaciones<input id="mdq" type="number" step="0.00000001"></label><label>Precio / valor unitario<input id="mdpu" type="number" step="0.00000001"></label><label>Valor total<input id="mdvt" type="number" step="0.00000001"></label><label class="full">Observaciones<textarea id="mdo"></textarea></label></div>'}
async function saveManual(){const id=$('mdp').value,fecha=$('mdf').value,p=S.p.find(x=>x.id===id);const isPension=p&&String(tn(p)).toLowerCase().includes('pension');if(account(p)){const r=await db.from('valoraciones_historicas').insert({user_id:S.user.id,producto_id:id,fecha,valor_total:Number($('mdv').value)||0,origen:'manual',fuente:'Usuario',es_valida:true,prioridad_origen:100,observaciones:$('mdo').value});if(r.error)return alert(r.error.message)}else{const qtyIn=Number($('mdq').value)||0,pu=Number($('mdpu').value)||0,total=Number($('mdvt').value)||qtyIn*pu;if($('mdt').value==='operacion'){const r=await db.from('operaciones').insert({user_id:S.user.id,producto_id:id,fecha,tipo_operacion:'Aportación',cantidad:qtyIn,precio_unitario:pu,importe_neto:total,moneda:'EUR',observaciones:$('mdo').value});if(r.error)return alert(r.error.message)}else if(isPension){const r=await db.from('cotizaciones_historicas').insert({user_id:S.user.id,producto_id:id,fecha,cierre:pu||total,moneda:'EUR',tipo_precio:pu?'Valor liquidativo':'Valoración total',cantidad:qtyIn||null,valor_total:total,origen:'manual',fuente:'Usuario',es_valida:true,prioridad_origen:100,observaciones:$('mdo').value});if(r.error)return alert(r.error.message)}else{const r=await db.from('valoraciones_historicas').insert({user_id:S.user.id,producto_id:id,fecha,cantidad:qtyIn,precio_unitario:pu,valor_total:total,origen:'manual',fuente:'Usuario',es_valida:true,prioridad_origen:100,observaciones:$('mdo').value});if(r.error)return alert(r.error.message)}}closeM();load()}
let multiAccountRows=[];
function multiAccountData(){const id=$('mdp').value,p=S.p.find(x=>x.id===id);if(!account(p))return alert('Solo disponible para cuentas corrientes y de ahorro.');multiAccountRows=[{fecha:today(),saldo:'',obs:''}];modalBox.innerHTML='<div class="toolbar"><div><h2>Introducción múltiple de saldos</h2><div class="sub">'+esc(p.nombre)+'</div></div><button class="btn alt" onclick="manualData(\''+id+'\')">Volver</button></div><p class="sub">Añade una fila por fecha. Revisa los datos antes de guardarlos todos juntos.</p><div id="multiAccountTable"></div><div class="toolbar" style="margin-top:14px;justify-content:flex-start"><button class="btn alt" onclick="addMultiAccountRow()">+ Añadir fila</button><button class="btn" onclick="saveMultiAccount(\''+id+'\')">Guardar todos</button><button class="btn alt" onclick="closeM()">Cancelar</button></div>';renderMultiAccountRows();modal.classList.add('open')}
function renderMultiAccountRows(){const el=$('multiAccountTable');if(!el)return;el.innerHTML='<div style="overflow:auto"><table style="width:100%;border-collapse:collapse;min-width:650px"><thead><tr><th style="text-align:left;padding:9px">Fecha</th><th style="text-align:left;padding:9px">Saldo (€)</th><th style="text-align:left;padding:9px">Observaciones</th><th></th></tr></thead><tbody>'+multiAccountRows.map((r,i)=>'<tr><td style="padding:5px"><input type="date" value="'+esc(r.fecha)+'" onchange="updateMultiAccountRow('+i+',\'fecha\',this.value)" required></td><td style="padding:5px"><input type="text" inputmode="decimal" placeholder="0,00" value="'+esc(r.saldo)+'" onchange="updateMultiAccountRow('+i+',\'saldo\',this.value)" style="width:100%"></td><td style="padding:5px"><input type="text" value="'+esc(r.obs)+'" onchange="updateMultiAccountRow('+i+',\'obs\',this.value)" style="width:100%"></td><td><button class="btn red" onclick="removeMultiAccountRow('+i+')">Eliminar</button></td></tr>').join('')+'</tbody></table></div><div class="sub" style="margin-top:8px">'+multiAccountRows.length+' filas preparadas</div>'}
function updateMultiAccountRow(i,k,v){multiAccountRows[i][k]=v}
function addMultiAccountRow(){multiAccountRows.push({fecha:today(),saldo:'',obs:''});renderMultiAccountRows()}
function removeMultiAccountRow(i){if(multiAccountRows.length===1)return alert('Debe quedar al menos una fila.');multiAccountRows.splice(i,1);renderMultiAccountRows()}
function parseSaldoManual(v){let s=String(v??'').trim().replace(/\s/g,'');if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');return Number(s)}
async function saveMultiAccount(id){const p=S.p.find(x=>x.id===id);if(!account(p))return alert('Solo disponible para cuentas corrientes y de ahorro.');const seen=new Set(),payload=[];for(let i=0;i<multiAccountRows.length;i++){const r=multiAccountRows[i],saldo=parseSaldoManual(r.saldo);if(!r.fecha||String(r.saldo).trim()===''||!Number.isFinite(saldo))return alert('Revisa la fecha y el saldo de la fila '+(i+1)+'.');if(seen.has(r.fecha))return alert('Hay fechas repetidas: '+r.fecha+'. Corrígelas antes de guardar.');seen.add(r.fecha);payload.push({user_id:S.user.id,producto_id:id,fecha:r.fecha,valor_total:saldo,origen:'manual',fuente:'Usuario',es_valida:true,prioridad_origen:100,observaciones:r.obs||null})}if(!confirm('¿Guardar los '+payload.length+' saldos de '+p.nombre+'?'))return;const res=await db.from('valoraciones_historicas').insert(payload);if(res.error)return alert('No se guardaron los datos: '+res.error.message);alert('Se han guardado '+payload.length+' saldos correctamente.');closeM();await load();product(id)}
function operationForm(id){modalBox.innerHTML=`<h2>Nueva operación</h2><div class="form"><label>Producto<select id="opP">${active().map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.nombre)}</option>`).join('')}</select></label><label>Fecha<input id="opF" type="date" value="${today()}"></label><label>Tipo<select id="opT"><option>Compra</option><option>Venta</option><option>Aportación</option><option>Dividendo en acciones</option><option>Acciones liberadas</option><option>Split</option><option>Traspaso</option><option>Ajuste de posición</option><option>Dividendo en efectivo</option><option>Prima de emisión</option><option>Venta de derechos</option></select></label><label>Cantidad<input id="opQ" type="number" step="0.00000001"></label><label>Precio unitario<input id="opPrc" type="number" step="0.00000001"></label><label>Importe neto<input id="opN" type="number" step="0.01"></label><label class="full">Observaciones<textarea id="opO"></textarea></label></div><br><button class="btn" onclick="saveOp()">Guardar</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveOp(){const r=await db.from('operaciones').insert({user_id:S.user.id,producto_id:$('opP').value,fecha:$('opF').value,tipo_operacion:$('opT').value,cantidad:Number($('opQ').value)||0,precio_unitario:Number($('opPrc').value)||0,importe_neto:Number($('opN').value)||0,moneda:'EUR',observaciones:$('opO').value});if(r.error)alert(r.error.message);else{closeM();load()}}
function interestForm(){modalBox.innerHTML=`<h2>Añadir interés</h2><div class="form"><label>Cuenta<select id="ip">${S.p.filter(account).map(p=>`<option value="${p.id}">${esc(p.nombre)}</option>`).join('')}</select></label><label>Fecha<input id="ifd" type="date" value="${today()}"></label><label>Bruto<input id="ib" type="number" step="0.01"></label><label>Retención<input id="ir" type="number" step="0.01"></label><label>Neto<input id="inet" type="number" step="0.01"></label><label class="full">Observaciones<textarea id="io"></textarea></label></div><br><button class="btn" onclick="saveInterest()">Guardar</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveInterest(){const b=Number($('ib').value)||0,r=Number($('ir').value)||0,n=$('inet').value===''?b-r:Number($('inet').value);const x=await db.from('intereses_cuentas').insert({user_id:S.user.id,producto_id:$('ip').value,fecha:$('ifd').value,importe_bruto:b,retencion:r,importe_neto:n,moneda:'EUR',origen:'manual',observaciones:$('io').value});if(x.error)alert(x.error.message);else{closeM();load()}}
function capture(id){modalBox.innerHTML=`<h2>📎 Añadir documento al producto</h2><div class="notice">El archivo queda asociado al producto seleccionado y preparado para extraer datos de ese producto. No se modifica la cartera sin confirmación.</div><div class="form"><label>Producto<select id="cp">${active().map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.nombre)}</option>`).join('')}</select></label><label>Fecha<input id="cf" type="date" value="${today()}"></label><label class="full">Archivo<input id="file" type="file" accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.csv"></label><label class="full">Observaciones<textarea id="co"></textarea></label></div><br><button class="btn" onclick="saveCapture()">Guardar y preparar revisión</button> <button class="btn alt" onclick="closeM()">Cancelar</button>`;modal.classList.add('open')}
async function saveCapture(){const f=$('file').files[0];if(!f)return alert('Selecciona un archivo.');const path=S.user.id+'/'+Date.now()+'_'+f.name.replace(/[^a-zA-Z0-9._-]/g,'_');const u=await db.storage.from('patrimonio-documentos').upload(path,f,{upsert:false});if(u.error)return alert(u.error.message);const r=await db.from('documentos_capturas').insert({user_id:S.user.id,producto_id:$('cp').value,fecha_documento:$('cf').value,archivo_nombre:f.name,archivo_tipo:f.type,archivo_path:path,estado:'pendiente_revision',datos_detectados:{},datos_confirmados:{},observaciones:$('co').value});if(r.error)alert(r.error.message);else{closeM();load()}}
async function activate(id){const r=await db.from('productos').update({activo:true}).eq('id',id).eq('user_id',S.user.id);if(r.error)alert(r.error.message);else load()}
async function deactivate(id){if(!confirm('¿Pasar este producto a Inactivos?'))return;const r=await db.from('productos').update({activo:false}).eq('id',id).eq('user_id',S.user.id);if(r.error)alert(r.error.message);else{closeM();load()}}
function closeM(){modal.classList.remove('open')}
function render(){const tabs=[['resumen','🏠 Resumen'],['entidades','🏦 Entidades'],['categorias','📊 Categorías'],['biblioteca','📚 Biblioteca'],['importar','📥 Importar históricos'],['inactivos','📁 Inactivos'],['intereses','💶 Intereses'],['fuentes','🌐 Fuentes']];$('app').innerHTML=`<div class="wrap"><div class="top"><div class="brand"><h1>Patrimonio</h1><p>Tu patrimonio, en un solo lugar</p></div><button class="btn alt" onclick="logout()">Salir</button><button class="btn" onclick="capture()">📄 Captura inteligente</button></div><div class="tabs">${tabs.map(x=>`<button class="tab ${S.tab===x[0]?'active':''}" onclick="S.tab='${x[0]}';render()">${x[1]}</button>`).join('')}</div>${S.tab==='resumen'?summary():S.tab==='entidades'?entities():S.tab==='categorias'?categories():S.tab==='biblioteca'?library():S.tab==='importar'?historyImporter():S.tab==='inactivos'?inactive():S.tab==='intereses'?interests():sources()}</div>`}
window.addEventListener('error',e=>{const a=$('app');if(a)a.innerHTML='<div class="wrap"><div class="card error"><h2>Error de JavaScript</h2><p>'+esc(e.message||'Error desconocido')+'</p></div></div>'});load();